    private const string ExtensionJudgedExt = "# 扩展策略\n\n字段级新增与结构 bump 的区别；本档即「迁移记录」体例说明。\n\n"
        + "- additive：只增不删\n- editorial：措辞与排版\n- 结构 bump：结构性演进\n"
        + "- 派生三问：谁读、读什么、坏了怎么办\n";

